```tsx
import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  componentStack: string | null;
  errorId: string | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, componentStack: null, errorId: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    const errorId = `err_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`;

    console.error("[ErrorBoundary]", {
      errorId,
      message: error.message,
      stack: error.stack,
      componentStack: info.componentStack,
    });

    this.props.onError?.(error, info);
    this.setState({ componentStack: info.componentStack ?? null, errorId });
  }

  reset = (): void => {
    this.setState({ error: null, componentStack: null, errorId: null });
  };

  render(): ReactNode {
    const { error, componentStack, errorId } = this.state;

    if (error) {
      if (this.props.fallback) return this.props.fallback(error, this.reset);

      return (
        <div
          role="alert"
          style={{
            padding: "1rem",
            border: "1px solid red",
            borderRadius: "4px",
            fontFamily: "monospace",
          }}
        >
          <h2 style={{ marginTop: 0 }}>Something went wrong</h2>
          <p style={{ color: "red" }}>{error.message}</p>
          {componentStack && (
            <details>
              <summary style={{ cursor: "pointer" }}>Component stack</summary>
              <pre style={{ whiteSpace: "pre-wrap", fontSize: "0.8rem", marginTop: "0.5rem" }}>
                {componentStack}
              </pre>
            </details>
          )}
          {errorId && (
            <p style={{ fontSize: "0.75rem", color: "#666" }}>Error ID: {errorId}</p>
          )}
          <button onClick={this.reset}>Try Again</button>
        </div>
      );
    }

    return this.props.children;
  }
}
```

**Changes from original:**

| What | Change |
|------|--------|
| `fallback` prop | Now render prop `(error, reset) => ReactNode` — gives consumers access to error + retry |
| `onError` prop | New escape hatch for external loggers (Sentry, DataDog, etc.) |
| `errorId` | Generated in `componentDidCatch`, shown in UI + logged — correlates UI display to console |
| Logging | Structured object with `errorId`, `message`, `stack`, `componentStack` instead of positional args |
| Default fallback | Shows `componentStack` in collapsible `<details>`, `errorId` for support reference |
| `reset` clears `errorId` | Full state wipe on retry |

**Usage:**

```tsx
// Default fallback
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback with retry
<ErrorBoundary fallback={(err, reset) => (
  <MyCustomError message={err.message} onRetry={reset} />
)}>
  <MyComponent />
</ErrorBoundary>

// With external logger
<ErrorBoundary onError={(err, info) => Sentry.captureException(err)}>
  <MyComponent />
</ErrorBoundary>
```

